static inline bool consume_string(pni_consumer_t *consumer, pn_bytes_t *string) {
  uint8_t type;
  *string = (pn_bytes_t){.size=0, .start=0};
  if (!pni_consumer_readf8(consumer, &type)) return false;
  switch (type) {
    case PNE_STR32_UTF8: {
